sequence.block:
// Helper variables
__var savedAP = __ap;
__var ffcrValue = 0x00000000;
__var etfStatus = 0x00000000;

Message(0, "Begin CS_ETF___INSTANCE_INDEX_____INSTANCE_INDEX___Configure_HWFIFO @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);
__ap = ETF___INSTANCE_INDEX___AP; // Set AP

// Configure ETF to HW FIFO for Sync Trace
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);  // Disable ETF before configuring
etfStatus = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var savedAP = __ap;
__var ffcrValue = 0x00000000;
__var etfStatus = 0x00000000;
__var traceBufferSyncCnt = 0xA;

Message(0, "Begin CS_ETF___INSTANCE_INDEX_____INSTANCE_INDEX___Configure_CircularBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);
__ap = ETF___INSTANCE_INDEX___AP; // Set AP

// Configure ETF to HW FIFO for Sync Trace
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);  // Disable ETF before configuring
etfStatus = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var ffcrValue = 0x00000000;
__var savedAP = __ap;
__var traceBufferSyncCnt = 0xA;

Message(0, "Begin CS_ETF___INSTANCE_INDEX_____INSTANCE_INDEX___Capture_CircularBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

// Ensure involved components are in a well-defined state.
Sequence("DoTraceFlush");

__ap = ETF___INSTANCE_INDEX___AP; // Set AP
ffcrValue  = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue |= 0x00000002;               // FFCR: Enable Formatter
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x308, traceBufferSyncCnt); // Set PSCR
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x018, 0x00000000);  // Init RwP
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x014, 0x00000000);  // Init RRP
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000001);  // Enable ETF
__ap = savedAP;

Message(0, "End CS_ETF___INSTANCE_INDEX_____INSTANCE_INDEX___Capture_CircularBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

// Helper variables
__var savedAP     = __ap;
__var ffcrValue   = 0x00000000;
__var etfStatus   = 0x00000000;

Message(0, "Begin CS_ETF___INSTANCE_INDEX_____INSTANCE_INDEX___Flush @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

__ap = ETF___INSTANCE_INDEX___AP; // Set AP

// Flush ETF first so the HW FIFO drains towards the TPIU.
ffcrValue = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue &= ~(0x00001040); // Clear StopOnFlush and FlushOnManual
ffcrValue |= 0x00001000;    // Stop after the manual flush completes
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
ffcrValue |= 0x00000040;    // Trigger manual flush
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);

// Disable ETF after flush until next run/step
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);
etfStatus = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var savedAP       = __ap;
__var etfStatus     = 0x00000000;
__var bufferSize    = 0x00000000;
__var readPointer   = 0x00000000;
__var writePointer  = 0x00000000;
__var bytesToRead   = 0x00000000;
__var bytesStreamed = 0x00000000;

Message(0, "Begin CS_ETF___INSTANCE_INDEX_____INSTANCE_INDEX___ReadBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

__ap = ETF___INSTANCE_INDEX___AP; // Set AP

// TMC RSZ is expressed in 32-bit words. RRP and RWP are byte offsets.
bufferSize   = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x004) * 4;
etfStatus    = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);
readPointer  = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x014);
writePointer = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x018);

control.block:
// STS.Full distinguishes a wrapped/full buffer from an empty buffer
// when the read and write pointers are equal.
bytesToRead = bufferSize;

// Read repeatedly from the TMC RRD register. The TMC advances RRP.
BufferRead(0, 0, ETF___INSTANCE_INDEX___ADDRESS + 0x010, bytesToRead, 32);
bytesStreamed = BufferStreamOut(0, 0, bytesToRead, ".trace/TraceBufferOutput.TB.raw", 0, 0);
Message(0, "Streamed %d of %d ETF trace bytes", bytesStreamed, bytesToRead);
